<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">feluqa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> module</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> disable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> sales.loyalty</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # feature toggle</span></span>
